// Pure movement-to-animation decisions. Animation clips themselves are
// authored and imported (e.g. glTF), not automatically generated by the engine.
export function chooseLocomotionClip({speed=0,grounded=true,verticalSpeed=0}={},available=[],{
  walkThreshold=.12,runThreshold=5,airThreshold=.15
}={}){
  if(![speed,verticalSpeed,walkThreshold,runThreshold,airThreshold].every(
    value=>typeof value==='number'&&Number.isFinite(value))||
    speed<0||walkThreshold<0||runThreshold<=walkThreshold||airThreshold<0)
    throw new TypeError('Invalid locomotion speed or animation thresholds');
  if(typeof grounded!=='boolean')throw new TypeError('grounded must be a boolean');
  const clips=available instanceof Set?available:new Set(available);
  const first=(...names)=>names.find(name=>clips.has(name))??null;
  if(!grounded)
    return verticalSpeed>airThreshold?
      first('jump','fall','idle','walk','run'):
      first('fall','jump','idle','walk','run');
  if(speed>=runThreshold)return first('run','walk','idle');
  if(speed>=walkThreshold)return first('walk','run','idle');
  return first('idle','walk','run');
}
